------------ import ------------
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool
local MAXENERGYNUM = 6
------------ import ------------

---@class UICommonHpAndEnergyNode                         
---@field Env                           	UIFightChooseCardsCardCellNode          
---@field controller                    	Engine.Modules.LuaBehaviour             
local UICommonHpAndEnergyNode = Class("UICommonHpAndEnergyNode")

function UICommonHpAndEnergyNode:__init()
    self._data = nil
end

function UICommonHpAndEnergyNode:__delete()
    self._data = nil
end

function UICommonHpAndEnergyNode:Awake()
end

function UICommonHpAndEnergyNode:Refresh(data)
    if not data then
        return
    end
    self._data = data

    self:FillHp(data.hpPercent)
    for i = 1, MAXENERGYNUM do
        local go = self.EnergyBgs.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.NoActImg, self.EnergyBgs)
            go.name = "go"..i
        end
        KTool.SetActive(go, i <= MAXENERGYNUM)


        go = self.Energys.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ActImg, self.Energys)
            go.name = "go"..i
        end
        KTool.SetActive(go, i <= checkNumber(data.energy))
    end
end

---RefreshCardHpEnergy 绘制卡牌的
---@param data table @ 血量数据
---@param maxEnergyNum integer
function UICommonHpAndEnergyNode:RefreshCardHpEnergy(data, maxEnergyNum)
    if not data then
        return
    end
    self._data = data
    self:FillHp(data.hpPercent, data.hpPercentAdd)
    local parGo = self.controller.gameObject.transform:Find("Energys")

    --[[
    for i = 1, MAXENERGYNUM do
        local go = self["Energy"..i]
        if go then
            KTool.SetActive(go, i <= checkNumber(maxEnergyNum))
        end
    end
    ]]

    KTool.SetActive(parGo, true)
    for i = 1, checkNumber(data.energy) do
        local go = self["Energy"..i]
        CfUtils.SetUISwitchImage(go, 1)
        KTool.SetActive(go, true)
    end

    if checkNumber(data.energy) < MAXENERGYNUM then 
        for i = checkNumber(data.energy) + 1, MAXENERGYNUM do
            local go = self["Energy"..i]
            --KTool.SetUISwitchImage(go, 2)
            KTool.SetActive(go, false)
        end
    end
end

---RefreshTeamDialogCardHpEnergy 绘制编队界面卡牌的
---@param data table @ 血量数据
---@param maxEnergyNum integer
function UICommonHpAndEnergyNode:RefreshTeamDialogCardHpEnergy(data, maxEnergyNum)
    if not data then
        return
    end
    self._data = data
    self:FillHp(data.hpPercent)

    local parGo = self.controller.gameObject.transform:Find("Energys")
    for i = 1, MAXENERGYNUM do
        local go = self["Energy"..i]
        if go then
            KTool.SetActive(go, i <= checkNumber(maxEnergyNum))
        end
    end
    KTool.SetActive(parGo, true)

    for i = 1, checkNumber(data.energy) do
        local go = self["Energy"..i]
        CfUtils.SetUISwitchImage(go, 1)
    end

    if checkNumber(data.energy) < MAXENERGYNUM then 
        for i = checkNumber(data.energy) + 1, MAXENERGYNUM do
            local go = self["Energy"..i]
            CfUtils.SetUISwitchImage(go, 2)
        end
    end
end

function UICommonHpAndEnergyNode:FillHp(hpPercent, hpPercentAdd)
    local hpBgCache = self.controller.transform:Find('HpBgCache')
    if isNotNull(hpBgCache) then
        -- UITeamMemberNode.prefab 专用更新行为
        local hpSlider = self.controller.transform:Find('HpBg')
        CfUtils.SetSliderPercent(hpSlider, checkNumber(hpPercent))
        local hpAddSliderImg = hpBgCache.transform:Find("Hp")
        CfUtils.SetActive(hpAddSliderImg, hpPercentAdd ~= nil)
        if hpPercentAdd then
            CfUtils.SetSliderPercent(hpBgCache, checkNumber(hpPercent) + checkNumber(hpPercentAdd))
        end
    else
        -- 老模式兼容，我看至少有个4个prefab使用
        self.HpBg.value = checkNumber(hpPercent)
        -- CfUtils.SetUISwitchImage(self.HpBg.transform:Find("Hp"), checkNumber(hpPercent) <= 0 and 2 or 1)
    end
end

function UICommonHpAndEnergyNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UICommonHpAndEnergyNode





